
import { inversifyContainer } from '../../../../inversify/container';

import { Injects } from '../../../../inversify/injects';
import { PropType } from 'vue';
import { ISpinSymbolPayoutData, ISymbolsInfo } from '../../../../types';

import { BaseComponent } from '../base-component';

export default BaseComponent.extend({
    name: 'SymbolsAndPayouts',
    props: {
        symbols: { type: Array as PropType<ISymbolsInfo[][]>, required: true },
        color: { type: String, required: false, default: 'orange' },
    },
    methods: {
        maxSymbolWidth(i: number) {
            return 100 / this.symbols[i].length + '%';
        },
        getText(symbolID: number) {
            const symbolData: ISpinSymbolPayoutData[] = inversifyContainer.get(Injects.SymbolPayoutData);

            for (let i = 0; i < symbolData.length; i++) {
                if (symbolData[i].symbolID === symbolID) {
                    let string = '';
                    for (let j = 0; j < symbolData[i].payout.length; j++) {
                        const matched = symbolData[i].payout[j].matched;
                        const multiplier = symbolData[i].payout[j].multiplier;
                        const stake = inversifyContainer.stake.currentStake;
                        const payout = inversifyContainer.currencyFormatter.precise(stake * multiplier);
                        string += `<span style="color: ${this.color};">x${matched}</span> = ${payout}`;
                        if (j !== symbolData[i].payout.length - 1) {
                            string += '<br>';
                        }
                    }
                    return string;
                }
            }

            return 'error fetching symbol data, have you bound it correctly?';
        }
    },
});